"""Sample records."""


class Sample:
    def __init__(self, batch, dose):
        self.batch = batch
        self.dose = dose

    def __repr__(self):
        return "Sample(%r, %r)" % (self.batch, self.dose)


ROWS = [('b2', 43), ('b1', 30), ('b2', 29), ('b3', 19), ('b2', 12), ('b2', 44)]


def load_samples():
    """Yield the stored samples one at a time."""
    for batch, dose in ROWS:
        yield Sample(batch, dose)


def feed_samples():
    """Endless feed of samples: repeats the stored rows for ever."""
    while True:
        for batch, dose in ROWS:
            yield Sample(batch, dose)
